mapper.select:
SELECT 
FROM pet_items
WHERE account_id = #{accountId}
  AND item_id = #{itemId}

mapper.insert:
INSERT INTO pet_items (
    account_id, item_id, count, updated_at
)
SELECT #{accountId}, #{itemId}, #{quantity}, #{updatedAt}
WHERE #{quantity} <= #{maxCount}
ON CONFLICT(account_id, item_id) DO UPDATE
SET count = count + excluded.count,
    updated_at = excluded.updated_at
WHERE pet_items.count + excluded.count <= #{maxCount}

mapper.update:
UPDATE pet_items
SET count = count - #{quantity},
    updated_at = #{updatedAt}
WHERE account_id = #{accountId}
  AND item_id = #{itemId}
  AND count >= #{quantity}
